-- stg_mp_strains: 107 rows. NOT APPLIED, branch only.
-- Licence from the FILENAME - this grid export carries no title block and no
-- licence column, so no in-file confirmation is possible. Stated, not implied.
create table if not exists public.stg_mp_strains (
  strain text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  licence_evidence text not null,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mp_strains enable row level security;
drop policy if exists stg_mp_strains_read on public.stg_mp_strains;
create policy stg_mp_strains_read on public.stg_mp_strains for select to authenticated using (true);
